begin
             Clear;
             if x = 50 then
             if wantenter('GROUND GATE') then begin
                with party do begin
                   xaxis := 50; yaxis := 10; map := 8;
                end;
                load;
                scroll(TRUE);
             end;
             if (x = 30) or (x = 32) then begin
                map[31,y] := 45;
