              end;
              if (y = 44) and (party.etc[33] and bit8 = 0) then begin
                 Clear;
                 Print(7,'당신은 어떤 창을 발견했다.');
                 PressAnyKey;
                 Print(7,'그 창의 손잡이에 쓰인 문구를 따르면..');
                 Print(7,'');
                 Print(11,'        이것은 오이디푸스의 창');
                 Print(11,'   이것으로 전에 Sphinx 를 무찌르다');
                 PressAnyKey;
                 Print(11,'누가 오이디푸스의 창을 다루겠습니까 ?');
                 k := choosewhom(FALSE);
                 if k = 0 then begin
                    asyouwish;
                    exit;
                 end;
                 if player[k].class = 5 then begin
                    message(7,'전투승은 이 무기가 필요없습니다.');
                    exit;
                 end;
                 with player[k] do begin
                    weapon := 3;
                    wea_power := 12;
                    if class = 1 then wea_power := wea_power + round(wea_power * 0.5);
                    message(15,name+' 가 오이디푸스의 창을 장착했다.');
                 end;
                 party.etc[33] := party.etc[33] or bit8;
              end;
              if y = 46 then
              if wantexit then begin
                 with party do begin
                    xaxis := 38; yaxis := 7; map := 7;
                 end;
                 load; scroll(TRUE);
                 for i := 1 to 6 do if player[i].name = 'Polaris' then map[37,41] := 44;
              end;
              if (y=24) and (party.etc[13]=1) then begin
                 Clear;
                 Print(11,'당신은 미이라의 방을 발견했다.');
                 PressAnyKey;
                 enemynumber := 3;
                 for i := 1 to 2 do begin
                    joinenemy(i,35);
                    with enemy[i] do begin
                       name := 'Sphinx';
                       level := 4;
                       special := 0;
                       E_number := 20;
                    end;
                 end;
                 joinenemy(3,26);
                 with enemy[3] do begin
                    name := 'Major Mummy';
                    ac := 1;
                 end;
                 Displayenemies(TRUE);
                 BattleMode(FALSE);
                 if party.etc[6] = 255 then exit;
                 if (party.etc[6]=0) or (enemy[3].hp<=0) then begin
                    Clear;
                    Print(15,'당신들은 Major Mummy 물리쳤다.');
                    Print(11,'그리고 당신은 이 임무에 성공했다.');
                    PressAnyKey;
                    inc(party.etc[13]);
                 end;    
              end;
           end

begin
      if at(51,55) then
         talk('LASTDITCH 성과 VALIANT PEOPLES 성은 매우 닮았다는 말이 있습니다.');
      if at(8,44) then
         talk('이 세계는 다섯개의 대륙으로 되어 있다더군요.');
      if at(68,35) then
         talk('각각의 대륙에는 서로 통하는 문이 존재합니다.');
      if at(43,9) then
         talk('당신은 PYRAMID 안에서 쉽게 창을 발견할 수 있을것입니다.');
      if at(65,10) then
         talk('GROUND GATE 는 여기로부터 서쪽에 나타나곤 합니다.');
      if at(14,68) then
         talk('LORE 특공대의 지휘관은 저의 남편인데 `Lore Hunter''라고 불렸습니다.');
      if at(57,42) then
         talk('Major Mummy 와 두마리의 Sphinx 의 공격은 가히 치명적입니다.');
      if at(44,34) then
         talk('GROUND GATE 는 당신을 다른 대륙으로 인도해 줄것입니다.');
      if at(32,56) then
         talk('LORE 특공대의 지휘관은 상당히 능력있는 인물이었습니다.');
      if at(36,19) or at(36,21) or at(41,18) or at(41,20) or at(41,22) or at(40,41) then
      if party.etc[13] = 0 then talk('성주님을 만나 보십시오.')
      else talk('당신이 성공하기를 빕니다.');
      if at(37,41) and (party.etc[13]<2) then begin
         cPrint(7,11,'나의 이름은 ','Polaris',' 요.');
         Print(7,'당신들과 같이 Major Mummy 를 물리치고 싶소.');
         Print(10,'내가 당신의 일행에 끼여도 되겠소 ?');
         m[0] := '';
         m[1] := '나는 당신의 제안을 받아 들이겠소';
         m[2] := '나는 당신의 도움은 필요 없소';
         k := select(125,2,2,FALSE,TRUE);
         if k = 1 then begin
            k := ReturnJoinMember;
            if k = 1 then exit;
            join(9,k);
            with player[k] do begin
               name := 'Polaris';
               class := 4;
               level[2] := 3;
               weapon := 4;
               shield := 1;
               armor := 1;
               wea_power := 10;
               shi_power := 1;
               arm_power := 2;
               ac := 3;
            end;
            Display_Condition;
            map[37,41] := 44;
            Silent_Scroll;
         end
         else asyouwish;
      end;
      if at(18,19) or at(24,19) or at(21,21) or at(16,24) then train_center;
      if at(57,17) or at(54,20) or at(58,22) or at(59,25) then grocery;
      if at(59,56) or at(59,58) or at(59,60) then weapon_shop;
      if at(17,56) or at(17,58) or at(17,60) then hospital;
      if at(38,17) then
      case party.etc[13] of
         0 : begin
          Print(7,' 당신이 '+player[1].name+'이오 ?');
          Print(7,' 나는 Lord Ahn 에게 당신이 온다는 소식을 전');
          Print(7,'해받았소.  들었다시피 우리성에는  큰 문제가');
          Print(7,'있소. 그것은 이 성의 북쪽에 위치해있는 동굴');
          Print(7,'때문이오.  그 동굴때문에 우리들은 상당한 압');
          Print(7,'박을받고 있소.');
          cPrint(7,11,' 만약 당신들이 위대한 영웅이라면, ','PYRAMID','라');
          cPrint(7,11,'는 동굴에 있는 ','Major Mummy','를 처단해 주시오.');
          Print(7,' 당신들이 이 임무를 완수하면  나는 당신들에');
          Print(7,'게 도움에 대한 댓가를 치뤄주겠소.');
          talk('');
          inc(party.etc[13]);
             end;
         1 : begin
          cPrint(7,11,' 부탁하건데, PYRAMID의 ''','Major Mummy','''를 처단');
          Print(7,'해 주시오.');
          PressAnyKey;
             end;
         2 : begin
          Print(7,'당신의 성공에 경의를 표하오.');
          Print(11,'[EXP + 10000]');
          talk('당신의 도움 덕분에 우리의 성이 구제 되었소.');
          for i := 1 to 6 do if player[i].name <> '' then
          player[i].experience := player[i].experience + 10000;
          inc(party.etc[13]);
             end;
         3 : begin
          cPrint(7,11,' 이 성의 북동쪽에 ''','GROUND GATE',''' 라는것이 있');
          cPrint(7,11,'소. 만약 당신이 ''','GROUND GATE',''' 속에 들어간다');
          cPrint(7,11,'면 ''','VALIANT PEOPLES','''성으로 통하게 될것이오.');
          cPrint(7,11,'''','VALIANT PEOPLES','''는 Necromancer에게 매우 심');
          Print(7,'하게 영향을 받고있소.');

          PressAnyKey;
             end;
      end;
         end
